body:
Looks good and seems to be building and running fine (tested with GCC and LLVM).

Will need few extra changes after rebase:
```diff
diff --git a/drivers/d3d12/rendering_device_driver_d3d12.h b/drivers/d3d12/rendering_device_driver_d3d12.h
index 6b1aa53d57..ce0e64fa9b 100644
--- a/drivers/d3d12/rendering_device_driver_d3d12.h
+++ b/drivers/d3d12/rendering_device_driver_d3d12.h
@@ -146,7 +146,7 @@ class RenderingDeviceDriverD3D12 : public RenderingDeviceDriver {
        class CPUDescriptorsHeapPool;

        struct CPUDescriptorsHeapHandle {
-               ComPtr<ID3D12DescriptorHeap> heap;
+               Microsoft::WRL::ComPtr<ID3D12DescriptorHeap> heap;
                CPUDescriptorsHeapPool *pool = nullptr;
                uint32_t offset = 0;
                uint32_t base_offset = 0;
@@ -160,7 +160,7 @@ class RenderingDeviceDriverD3D12 : public RenderingDeviceDriver {
                Mutex mutex;

                struct FreeBlockInfo {
-                       ComPtr<ID3D12DescriptorHeap> heap;
+                       Microsoft::WRL::ComPtr<ID3D12DescriptorHeap> heap;
                        uint32_t global_offset = 0; // Global offset in an address space shared by all the heaps.
                        uint32_t base_offset = 0; // The offset inside the space of this heap.
                        uint32_t size = 0;
@@ -792,7 +792,7 @@ public:
        };

        struct PipelineInfo {
-               ComPtr<ID3D12PipelineState> pso;
+               Microsoft::WRL::ComPtr<ID3D12PipelineState> pso;
                const ShaderInfo *shader_info = nullptr;
                RenderPipelineInfo render_info;
        };
```
